// Reusable hand-drawn illustration library. Every icon is a set of stroke
// paths in a 100×100 box, so the board can draw it line by line.
const c = (cx: number, cy: number, r: number) =>
  `M${cx - r} ${cy} a${r} ${r} 0 1 0 ${2 * r} 0 a${r} ${r} 0 1 0 ${-2 * r} 0`;

